      "konteks": "Nilai tempat artinya posisi angka menentukan nilainya. Angka di kiri adalah puluhan (ikatan isi sepuluh), angka di kanan adalah satuan (yang lepas). Ajak anak mengikat sedotan atau lidi per sepuluh, lalu tanyakan: angka 3 pada 34 menunjukkan ikatan atau yang lepas?",
