      "konteks": "Sisi kubus adalah bidang datar yang membatasi kubus, seperti permukaan dadu. Ajak anak memegang dadu atau kotak kado, lalu menghitung permukaannya satu per satu sambil menyebut: atas, bawah, dan sisi-sisi samping.",
