      "konteks": "Segi banyak adalah bangun datar yang sisinya garis lurus dan punya pojok, misalnya segitiga dan persegi. Bangun lengkung sisinya melengkung mulus tanpa pojok, misalnya lingkaran. Minta anak menelusuri tepi tiap bangun dengan jari, lalu hitung hanya yang tepinya lurus.",
