      "konteks": "Dua bangun datar bisa disusun menjadi bangun baru. Beri anak dua segitiga dari kertas (gunting persegi menurut garis pojok ke pojok). Minta ia mencoba menempelkan sisi-sisi yang berbeda dan melihat hasilnya. Tanyakan: sisi mana yang membuat bentuknya menjadi persegi? Terima jawaban dengan kata-kata anak sendiri.",
