      "konteks": "Menyusun bangun datar artinya menggabungkan beberapa bangun menjadi bangun baru. Beri anak dua kartu persegi yang sama besar dan minta ia menempelkan sisinya rapat. Lalu tanyakan: apakah keempat sisi bentuk barunya masih sama panjang? Bandingkan dengan pintu atau buku tulis.",
