      "konteks": "Depan berarti lebih dekat ke kita yang melihat, belakang berarti lebih jauh. Atur dua benda di meja: satu dekat anak dan satu agak jauh, lalu minta anak menceritakan letaknya. Pada gambar, perhatikan benda mana yang lebih dekat (letaknya lebih ke bawah di lantai dan menutupi sebagian benda lain).",
