      "minimal": 2,
      "konteks": "Bangun datar dapat dipotong menjadi bangun lain. Beri anak kertas persegi panjang dan minta ia menggunting dari satu pojok ke pojok seberangnya. Lalu tanyakan: ada berapa potongan dan berapa pojok tiap potongan? Biarkan anak menyebutkan nama bangun yang ia lihat.",
