     {
      "jenis": "uraian",
      "tanya": "Ayah punya 34 kelereng. Ayah memberikan 16 kelereng kepada adik.\nBerapa kelereng Ayah sekarang? Tulis cara bersusun dan hasilnya.",
      "contoh": "34 - 16 = 18. Satuan 4 tidak cukup dikurangi 6, pinjam 1 puluhan: 14 - 6 = 8. Puluhan tinggal 2, 2 - 1 = 1. Sisa 18 kelereng.",
      "kunci": [
       [
        "18"
       ]
      ],
      "minimal": 1,
      "konteks": "Meminjam dipakai bila angka satuan di atas lebih kecil dari satuan yang dikurangkan. Puluhan di sebelahnya dipinjam 1, dan 1 puluhan itu menjadi 10 satuan yang ditambahkan ke satuan. Contoh 32 - 8: satuan 2 tidak cukup, pinjam 1 puluhan jadi 12 - 8 = 4, puluhan tinggal 2, hasilnya 24. Peragakan dengan 3 ikat lidi isi sepuluh dan 4 lidi lepas: buka satu ikat agar ada cukup lidi lepas untuk diambil.",
      "kisi": "MT2b",
      "bahas": "Pinjam 1 puluhan: 14 - 6 = 8. Puluhan tinggal 2, 2 - 1 = 1. Hasilnya 18."
     }
