      "konteks": "Segi banyak adalah bangun datar yang sisinya lurus, seperti segitiga dan persegi. Lingkaran bukan segi banyak karena tepinya melengkung. Ajak anak memeriksa tiap kelompok satu per satu: adakah satu bangun yang tepinya melengkung? Kalau ada, kelompok itu tidak cocok.",
