      "jawab": 3,
      "konteks": "Bangun datar bisa diurai menjadi bangun-bangun kecil. Ajak anak menunjuk dan mewarnai tiap bagian pada gambar satu per satu (di gambar tiap bagian sudah berbeda warna), lalu menghitungnya. Boleh juga menggunting kertas persegi menurut dua garis pojok ke pojok.",
      "kisi": "MT3d",
