      "konteks": "Bilangan dua angka dibentuk dari puluhan (angka kiri) dan satuan (angka kanan). Contoh 2 puluhan dan 5 satuan ditulis 25. Ajak anak membuat ikatan sedotan isi sepuluh, lalu menaruh sedotan lepas di sampingnya dan menuliskan angkanya.",
