      "konteks": "Kerucut runcing di satu ujung dan alasnya berbentuk lingkaran, seperti topi ulang tahun atau cone es krim. Ajak anak membayangkan atau menggambar topi ulang tahun, lalu mencari benda lain yang bentuknya serupa. Bandingkan dengan tabung yang atas dan bawahnya sama besar.",
