      "konteks": "Nama segitiga berasal dari \"tiga\": tiga sisi dan tiga pojok. Ajak anak menggambar bangun itu di kertas dengan tiga garis lurus, lalu menghitung sisi dan pojoknya. Contoh benda: penggaris segitiga dan rambu jalan tertentu.",
