      "konteks": "Pola warna berulang dengan urutan tetap. Minta anak menyebutkan warna dari kiri ke kanan: \"merah, merah, biru ...\". Bagian mana yang berulang? Lanjutkan menyebut kelompok itu sampai ke tanda tanya.",
