      "minimal": 1,
      "konteks": "Menyusun bangun datar berarti menempatkan bangun kecil rapat tanpa celah agar membentuk bangun yang lebih besar. Beri anak 4 kartu persegi yang sama besar dan minta ia mencoba berbagai susunan sampai bentuknya jadi persegi besar. Lalu minta ia menceritakan susunan yang berhasil: berapa kartu di atas dan di bawah?",
